  "Torrent engine said {status}.": "Торрент кыймылдаткычы {status} кайтарды.",
  "Torrent engine said {status}: {reason}": "Торрент кыймылдаткычы {status} кайтарды: {reason}",
  "Torrents": "Торренттер",
